 import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const group = new Group();
  group.userData.handlers = {};

  const cardWidth = 1.28;
  const cardHeight = 0.8;

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1
  });

  const plane = new Mesh(geometry, material);
  group.add(plane);

  let disposed = false;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose();
        return;
      }
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    if (!item.text) continue;
    if (item.role === 'headline' || item.role === 'title') {
      const label = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 39,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 2
      });
      label.position.set(0, 0.05, 0.01);
      label.scale.setScalar(0.0045);
      group.add(label);
    }
  }

  group.userData.cleanup = () => {
    disposed = true;
    if (material.map) {
      material.map.dispose();
      material.map = null;
    }
    geometry.dispose();
    material.dispose();
  };

  return group;
}
